"""Join hard-wrapped Markdown paragraph/list-item lines; leave every structural line alone."""
import re, sys

LIST = re.compile(r'^\s*([-*+]|\d+[.)])\s')
STARTS_BLOCK = re.compile(r'^\s*(#{1,6}\s|[-*+]\s|\d+[.)]\s|>|\||<|```|~~~|(---|\*\*\*|___)\s*$|\[\^?[^\]]+\]:\s)')
TRAILER = re.compile(r'^[A-Z][A-Za-z-]+: \S')
NO_JOIN_AFTER = re.compile(r'^\s*(#{1,6}\s|\||```|~~~|<|(---|\*\*\*|___)\s*$)')

def unwrap(text):
    out, fence, front, listy = [], False, False, False
    for i, line in enumerate(text.split("\n")):
        s = line.strip()
        if i == 0 and s == "---":
            front = True; out.append(line); continue
        if front:
            out.append(line); front = s != "---"; continue
        if s.startswith(("```", "~~~")):
            fence = not fence; out.append(line); listy = False; continue
        if fence or not s:
            out.append(line); listy = False if not s else listy; continue
        prev = out[-1] if out else ""
        indented_code = re.match(r'^ {4,}\S', line) and not listy
        can_join = (prev.strip() and not fence and not STARTS_BLOCK.match(line) and not TRAILER.match(line)
                    and not NO_JOIN_AFTER.match(prev) and not TRAILER.match(prev)
                    and not prev.endswith("  ") and not prev.rstrip().endswith("\\") and not indented_code)
        if can_join:
            out[-1] = prev.rstrip() + " " + s
        else:
            out.append(line); listy = bool(LIST.match(line))
    return "\n".join(out)

if __name__ == "__main__":
    path = sys.argv[1]
    res = unwrap(open(path).read())
    if "--write" in sys.argv: open(path, "w").write(res)
    else: sys.stdout.write(res)
